def sort_on_occurence(lst):
    """Write a function to sort the given list based on the occurrence of first element of tuples."""
    counts = {}
    grouped = {}
    order = []
    for item in lst:
        key = item[0]
        tail = item[1:]
        if key not in counts:
            counts[key] = 0
            grouped[key] = []
            order.append(key)
        counts[key] += 1
        grouped[key].extend(tail)
    result = [tuple([key] + grouped[key] + [counts[key]]) for key in order]
    result.sort(key=lambda t: t[-1], reverse=True)
    return result
